#!/usr/bin/env bash
# qa-fleet hook of {{PROJECT}}, GENERATED by `node qa-pack/runners/pack.mjs fleet-units` from qa.config.json:
# edit qa.config.json (fleet.setup, mobile.*) and regenerate, do not edit by hand.
# Called by the fleet runner from the repo root as: unit.sh setup|ready|run <unit-id>
# Kind of unit = $QAF_KIND (from .qa-fleet/units.json):
#   static   node only (validators, unit tests)
#   stack    the project stack + browsers (browser suites, backend layers)
#   mobile   stack + app build + Android emulator (booted by the runner meanwhile) + Maestro
# Exit 75 = environment problem (the fleet retries the unit once on another runner). Other exits are real failures.
# Never print a secret value.
set -uo pipefail
phase="${1:?phase}"; : "${2:?unit id}"
KIND="${QAF_KIND:-static}"
PROJECT_DIR="{{PROJECT_DIR}}"
TMPD="${RUNNER_TEMP:-/tmp}"
RUN_ENV="$TMPD/qaf-unit.env"            # PATH additions from setup, read again by ready/run
MAESTRO_VERSION={{MAESTRO_VERSION}}
MAESTRO_ZIP_SHA256={{MAESTRO_SHA256}}
infra() { echo "infra: $*"; exit 75; }
fail() { echo "FAILED: $*"; exit 1; }
# shellcheck disable=SC1090
[ -f "$RUN_ENV" ] && . "$RUN_ENV"

install_maestro() {
  command -v maestro >/dev/null && return 0
  [ -n "$MAESTRO_ZIP_SHA256" ] || fail "qa.config mobile.maestro.sha256 is not set (pin the Maestro zip checksum)"
  curl -fsSL -o "$TMPD/maestro.zip" "https://github.com/mobile-dev-inc/Maestro/releases/download/cli-${MAESTRO_VERSION}/maestro.zip" || infra "maestro download"
  echo "${MAESTRO_ZIP_SHA256}  $TMPD/maestro.zip" | sha256sum -c - >/dev/null || fail "maestro checksum mismatch"
  unzip -q -o "$TMPD/maestro.zip" -d "$TMPD/maestro-cli" || infra "maestro unpack"
  echo "export PATH=\"$TMPD/maestro-cli/maestro/bin:\$PATH\"" >>"$RUN_ENV"; export PATH="$TMPD/maestro-cli/maestro/bin:$PATH"
}

setup_static() { ( cd "$PROJECT_DIR" && {{SETUP_STATIC}} ) || infra "setup static"; }
setup_stack() {
  ( cd "$PROJECT_DIR" && {{SETUP_STACK}} ) || infra "setup stack"
  {{STACK_UP}}
}
setup_mobile() {
  install_maestro
  ( cd "$PROJECT_DIR" && {{SETUP_MOBILE}} ) || fail "mobile setup / app build"
}
ready_mobile() {
  export PATH="${ANDROID_HOME:-/usr/local/lib/android/sdk}/platform-tools:$PATH"
  adb wait-for-device || infra "adb"
  for p in {{REVERSE_PORTS}}; do adb reverse "tcp:$p" "tcp:$p" || infra "adb reverse $p"; done
  APK=$(cd "$PROJECT_DIR" && ls {{APK_GLOB}} 2>/dev/null | head -1)
  [ -n "$APK" ] || fail "no APK matching {{APK_GLOB}}"
  adb install -r -t "$PROJECT_DIR/$APK" || infra "adb install"
  adb shell pm list packages | grep -q "package:{{APP_ID}}" || infra "app {{APP_ID}} not installed"
}

case "$phase" in
  setup)
    : >"$RUN_ENV"
    case "$KIND" in
      static) setup_static ;;
      stack) setup_stack ;;
      mobile) setup_stack; setup_mobile ;;
    esac
    ;;
  ready)
    [ "$KIND" = mobile ] && ready_mobile
    exit 0
    ;;
  run)
    mkdir -p qa-fleet-results
    eval "$QAF_CMD"
    ;;
  *) exit 0 ;;
esac
